$script = @'
const fs=require('fs'), path=require('path');
const folder=path.join(process.cwd(),'3. SQL','17.10.2026');
const read=p=>fs.readFileSync(p,'utf16le').replace(/^\uFEFF/,'');
const write=(p,s)=>fs.writeFileSync(p,Buffer.concat([Buffer.from([0xff,0xfe]),Buffer.from(s,'utf16le')]));
const names=['SIM_SpecialBranch_Subject_Add','SIM_SpecialBranch_Subject_Edit','SIM_SpecialBranch_Subject_Update','SIM_SpecialBranch_Subject_Get','SIM_SpecialBranch_Subject_GetAll','SIM_SpecialBranch_Subject_Search','SIM_Class_Subject_Add','SIM_Class_Subject_EDIT','SIM_Class_Subject_Update','SIM_Class_Subject_Get','SIM_Class_Subject_GetAll','SIM_Class_Subject_Search','SIM_Class_Subject_ReSync_FromSBS'];
function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function compact(s){return s.replace(/^[\t ]*\r?\n/gm,'');}
let basePath=path.join(folder,'all - store.sql'), base=read(basePath);
for(const name of names){const re=new RegExp('^\\s*Create\\s+(?:Procedure|Proc)\\s+\\[dbo\\]\\.\\['+esc(name)+'\\][\\s\\S]*?(?=^GO\\s*$)','im');const m=re.exec(base);if(!m)throw new Error(name);base=base.slice(0,m.index)+compact(m[0])+base.slice(m.index+m[0].length);}
write(basePath,base);
for(const f of fs.readdirSync(folder).filter(f=>/^(0[3-9]|1[0-7])_20261017_.*minute_of_test\.sql$/i.test(f))){const p=path.join(folder,f);write(p,compact(read(p)));}
console.log('Removed blank lines from changed SQL blocks.');
'@; $script | node
